// ==========================================
// Arduino Uno R3: ไฟกะพริบ + สวิตช์ปุ่มกด + Serial Monitor
// เพียงเปลี่ยนหมายเลขขาด้านล่างก็ใช้งานได้ทันที
// ==========================================
#define LED_PIN    13    // ขาควบคุม LED (มี LED ในตัวที่ขา 13)
#define BUTTON_PIN 2     // ขาต่อสวิตช์ปุ่มกด (ต่อขาหนึ่งเข้า D2 อีกขาลง GND)

void setup() {
  pinMode(LED_PIN, OUTPUT);          // ตั้งขา LED เป็น Output
  pinMode(BUTTON_PIN, INPUT_PULLUP); // ใช้งาน Pull-up ภายในบอร์ด
  Serial.begin(9600);                // เปิด Serial Monitor ที่ความเร็ว 9600 baud
  Serial.println("Arduino Uno R3 is ready!");
}

void loop() {
  int buttonState = digitalRead(BUTTON_PIN);

  if (buttonState == LOW) { // เมื่อกดปุ่ม (สัญญานต่อลง GND)
    digitalWrite(LED_PIN, HIGH); // เปิดไฟ LED
    Serial.println("Button Pressed -> LED ON");
  } else {
    digitalWrite(LED_PIN, LOW);  // ปิดไฟ LED
  }
  delay(100); // หน่วงเวลาเล็กน้อยเพื่อเสถียรภาพ
}
